CREATE SEQUENCE IF NOT EXISTS Fix_Tot_Seq
  INCREMENT BY 1
  START WITH 1;

Create Table Fix_Tot					      -- جدول تجميعات الإهتلاك للسنوات المالية
( Id         BIGINT,					          -- مفتاح رئيسي
  FYear      SMALLINT,				              -- السنة
  FMonth     SMALLINT,				              -- الشهر
  FTrn_Id    BIGINT,					          -- بند الادخال
  Fixd_Id    BIGINT,					            -- المادة
  Vhr_Id     BIGINT,						        -- مفتاح الوثيقة المالية
  Curn_Id    BIGINT,         				    -- العملة
  Curn_Rate  NUMERIC(25,9) Default 1,        -- سعر الصرف
  Qnt        NUMERIC(25,3) Default 0,				-- الكمية
  CQnt       NUMERIC(25,3) Default 0,				-- الكمية الحالية
  Price      NUMERIC(25,3) Default 0,				-- سعر الوحدة
  Amt        NUMERIC(25,3) Default 0,				-- المبلغ
  CAmt       NUMERIC(25,3) Default 0,				-- المبلغ قطع
  Perc       NUMERIC(6,2) Default 1,				  -- نسبة الإهتلاك
  FTot       NUMERIC(25,3) Default 0,				-- مجمع سابق
  FAmt       NUMERIC(25,3) Default 0,				-- اهتلاك حالي
  RTot       NUMERIC(25,3) Default 0,				-- احتياطي سابق
  RAmt       NUMERIC(25,3) Default 0,				-- احتياطي حالي
  Ins_User   BIGINT, Ins_Date   TIMESTAMP,
  Upd_User   BIGINT, Upd_Date   TIMESTAMP,
  CONSTRAINT Fix_Tot_PK        PRIMARY KEY (Id ),
  CONSTRAINT Fix_Tot_UK        Unique      (FYear,FMonth,FTrn_Id),
  CONSTRAINT Fix_Tot_ITrn_FK   Foreign Key (FTrn_Id ) References Fix_InTrn(Id),
  CONSTRAINT Fix_Tot_Fixd_FK   Foreign Key (Fixd_Id ) References Fix_Fixed(Id),
  CONSTRAINT Fix_Tot_AccMst_FK Foreign Key (Vhr_Id  ) References Acc_Mst  (Id),
  CONSTRAINT Fix_Tot_Curn_FK   Foreign Key (Curn_Id ) References Mng_Curn (Id),
  CONSTRAINT Fix_Tot_Ins_FK    Foreign Key (Ins_User) References Cpy_User (Id),
  CONSTRAINT Fix_Tot_Upd_FK    Foreign Key (Upd_User) References Cpy_User (Id)
);

Create INDEX Fix_Tot_Year_IDX  ON Fix_Tot(FYear);

Create INDEX Fix_Tot_Month_IDX ON Fix_Tot(FMonth);

Create INDEX Fix_Tot_Fixd_IDX  ON Fix_Tot(Fixd_Id);

Create INDEX Fix_Tot_FTrn_IDX  ON Fix_Tot(FTrn_Id);

