  CQnt       NUMERIC(25,3) Default 0,				-- الكمية الحالية
  Price      NUMERIC(25,3) Default 0,				-- سعر الوحدة
  Amt        NUMERIC(25,3) Default 0,				-- المبلغ
  Perc       NUMERIC(6,2) Default 1,				  -- نسبة الإهتلاك
  FTot       NUMERIC(25,3) Default 0,				-- مجمع سابق
  FAmt       NUMERIC(25,3) Default 0,				-- اهتلاك حالي
